{
  "missing_information": [
    {
      "category": "actor",
      "gap": "No information on who is responsible for creating the meeting summary (e.g., meeting host, designated note-taker, rotating role, or an automated transcription tool).",
      "why_it_matters": "Identifying the actor determines whether summarization is a manual human task or already partially automated, directly affecting automation potential."
    },
    {
      "category": "input",
      "gap": "No details on the source material for the summary (e.g., handwritten notes, audio recording, video recording, chat transcript, shared document during meeting).",
      "why_it_matters": "The input format determines which automation tools (e.g., speech-to-text, AI summarization) are applicable and what integration is needed."
    },
    {
      "category": "system",
      "gap": "No information on the meeting platform used (e.g., video conferencing, in-person, phone), nor the email system used for distribution.",
      "why_it_matters": "System identification is essential to assess API availability, integration feasibility, and whether native automation hooks exist."
    },
    {
      "category": "decision",
      "gap": "No criteria defined for determining who the 'relevant people' are for email distribution (e.g., attendees only, additional stakeholders, management escalation).",
      "why_it_matters": "Without a clear rule for recipient selection, the distribution step cannot be automated reliably and may require manual judgment each time."
    },
    {
      "category": "output",
      "gap": "No standard format or template specified for the meeting summary (e.g., bullet points, action items section, decisions log, structured template).",
      "why_it_matters": "A lack of output standardization means automation cannot reliably generate or validate the summary content before sending."
    },
    {
      "category": "frequency",
      "gap": "No information on how often meetings occur, the volume of summaries produced per week or month, or whether meeting types vary (e.g., recurring vs. ad hoc).",
      "why_it_matters": "Frequency and volume data are critical for estimating automation ROI and prioritizing implementation effort."
    },
    {
      "category": "manual_effort",
      "gap": "No estimate of the time spent per meeting on summarization and email preparation, nor the total effort across the organization.",
      "why_it_matters": "Without effort estimates, it is impossible to quantify the automation benefit or build a business case."
    },
    {
      "category": "exception",
      "gap": "No information on exception cases such as confidential meetings, partially attended meetings, meetings with no clear outcomes, or failed email delivery.",
      "why_it_matters": "Unhandled exceptions can cause automation failures or data governance violations if sensitive content is distributed incorrectly."
    },
    {
      "category": "dependency",
      "gap": "No details on whether action items from the summary feed into downstream systems (e.g., task management, CRM, project tracking tools).",
      "why_it_matters": "If summaries trigger downstream workflows, a broader automation scope may be needed and integration dependencies must be mapped."
    },
    {
      "category": "data_availability",
      "gap": "No clarity on whether meeting recordings or transcripts are currently stored and accessible in a structured, retrievable format.",
      "why_it_matters": "Automation of summarization depends on having reliable, machine-readable input data; unavailability blocks AI-assisted approaches."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "Who currently creates the meeting summary, and what source material do they use (e.g., personal notes, recording, transcript)?",
      "targets": ["actor", "input"]
    },
    {
      "id": "Q2",
      "question": "Which platform is used to host meetings, and which email system is used to distribute the summary?",
      "targets": ["system", "integration_constraint"]
    },
    {
      "id": "Q3",
      "question": "How is the list of email recipients determined after each meeting — is it always the attendees, or does someone manually curate the distribution list?",
      "targets": ["decision", "actor"]
    },
    {
      "id": "Q4",
      "question": "Is there a standard template or required structure for the meeting summary (e.g., attendees, decisions, action items, deadlines), or does the format vary?",
      "targets": ["output", "input"]
    },
    {
      "id": "Q5",
      "question": "Approximately how many meetings per week require a summary and email, and how much time on average does the full process take per meeting?",
      "targets": ["frequency", "manual_effort"]
    },
    {
      "id": "Q6",
      "question": "Are there any meetings considered confidential or sensitive where the normal summarization and distribution process should not apply, and if so, how are these currently handled?",
      "targets": ["exception", "risk_or_approval"]
    }
  ]
}
